class DSU{
    public:
    vector<int> par;
    vector<int> sizes;
    DSU(int size){
        par.resize(size);
        sizes.resize(size);

        for(int i=0;i<par.size();i++)
            par[i] = i;
    }

    int findUP(int x){
        if(par[x]!=x) par[x] = findUP(par[x]);
        return par[x];
    }

    void uni(pair<int,int> cor1, pair<int,int> cor2, int m){
        int p1 = cor1.first + cor1.second * m;
        int p2 = cor2.first + cor2.second * m; 
        int up1 = findUP(p1);
        int up2 = findUP(p2);

        if(up1 == up2 ) return;

        if(sizes[up1] > sizes[up2]){
            par[up2] = up1;
            sizes[up1] += sizes[up2];
        }else{
            par[up1] = up2;
            sizes[up2] += sizes[up1];
        }
    }


    int islands(unordered_set<int> us){
        int cnt = 0;
        for(auto hash: us){
            if( par[hash] == hash) 
                cnt++;
        }

        return cnt;
    }
};

class Solution{
public:
vector<int> numOfIslands(int n, int m, vector<vector<int>> &A){
        swap(n,m);

        DSU dsu(m*n);
        unordered_set<int> us;

        int arr[] = { -1, 0, 1, 0, -1 };

        vector<int> ans;

        for(auto p: A){
            for(int i = 0;i<4;i++){
                int x = p[0] + arr[i];
                int y = p[1] + arr[i+1];
                if(x<0 || x>=m || y<0 || y>=n) continue;
                int hash = x + y * m;
                if(us.find(hash) != us.end()){
                        dsu.uni({ x, y }, { p[0], p[1] }, m);
                    }
                }
            int hash = p[0] + p[1] * m;
            us.insert(hash);
            ans.push_back(dsu.islands(us));
        }

        return ans;
    }
};

