class DSU {
    vector<int> parent;
    vector<int> sz;

public:
    DSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    bool group(int a, int b) {
        int pa = find(a);
        int pb = find(b);

        if (pa == pb) return false;

        if (sz[pa] < sz[pb]) {
            swap(pa, pb);
        }

        parent[pb] = pa;
        sz[pa] += sz[pb];

        return true;
    }
};



class Solution{
public:
vector<int> numOfIslands(int n, int m, vector<vector<int>>& A) {
    vector<vector<int>> grid(n, vector<int>(m, -1));

    DSU dsu(n * m);

    vector<int> ans;

    int cc = 0;

    int dx[4] = {0, 1, 0, -1};
    int dy[4] = {1, 0, -1, 0};

    for (auto &op : A) {
        int x = op[0];
        int y = op[1];

        if (grid[x][y] != -1) {
            ans.push_back(cc);
            continue;
        }

        grid[x][y] = x * m + y;
        cc++;

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            if (nx < 0 || nx >= n || ny < 0 || ny >= m)
                continue;

            if (grid[nx][ny] == -1)
                continue;

            if (dsu.group(grid[x][y], grid[nx][ny]))
                cc--;
        }

        ans.push_back(cc);
    }

    return ans;
}
};

